'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\n\n', [[''], ['']]],
  ['a\n', [['a']]],
  ['a\r\nb\rc', [['a'], ['b'], ['c']]],
  ['a\r\n\r\n', [['a'], ['']]],
  ['\uFEFFa,\uFEFF', [['a', '\uFEFF']]],
  ['a"b,"c""d"', [['a"b', 'c"d']]],
  ['"x\r\ny\rz\n",', [['x\r\ny\rz\n', '']]],
  ['"",""\n', [['', '']]],
  ['a,b,', [['a', 'b', '']]],
  ['"a"', [['a']]],
];
for (const [input, expected] of cases) {
  assert.deepEqual(parse(input), expected, JSON.stringify(input));
  // every split into single code units, plus empty chunks
  const p = createParser();
  let got = [];
  p.push('');
  for (const ch of input.split('')) { got = got.concat(p.push(ch)); p.push(''); }
  got = got.concat(p.end());
  assert.deepEqual(got, expected, 'chunked ' + JSON.stringify(input));
}

// immediate emission at CR before LF arrives
const p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), e => e.constructor === Error);

// line numbers
const lineOf = (chunks) => {
  const q = createParser();
  try { for (const c of chunks) q.push(c); q.end(); } catch (e) { assert.ok(e instanceof SyntaxError); return e.message; }
  return 'no error';
};
assert.match(lineOf(['a\r', '\n"x\r', '\ny" z']), /line 3/);
assert.match(lineOf(['a\n\n"b"c']), /line 3/);
assert.match(lineOf(['"a"\r\r"b" ']), /line 3/);
assert.match(lineOf(['x\n"abc\n']), /line 3/);
assert.match(lineOf(['"a"', '"', 'b"x']), /line 1/);

// delimiter
assert.deepEqual(parse('a;b\n"c;d";e', { delimiter: ';' }), [['a', 'b'], ['c;d', 'e']]);
assert.deepEqual(parse('a\tb', { delimiter: '\t' }), [['a', 'b']]);
for (const d of ['"', '\r', '\n', '', ';;', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);
assert.throws(() => createParser().push(1), TypeError);

// header
assert.deepEqual(parse('', { header: true }), []);
assert.deepEqual(parse('x,x\n1', { header: true }), [{ x: '1', x_2: '' }]);
assert.deepEqual(createParser({ header: true }).push('a\n'), [['a']]);
console.log('smoke ok');

